import { requireRole } from '@/lib/auth/server'
import { createClient } from '@/lib/supabase/server'
import { CuttingForm } from './CuttingForm'
import { logout } from '@/app/login/actions'

export default async function CuttingDashboard() {
    // 1. Authorize - Strict Server-side RBAC
    const session = await requireRole(['cutting_supervisor'])
    const supabase = await createClient()

    // 2. Fetch Recipes (with components) for the creation form
    const { data: recipes, error: recipesError } = await supabase
        .from('recipes')
        .select(`
            id, recipe_code, name, std_fabric_yards, wastage_cap,
            recipe_components(component_name, pieces_per_garment)
        `)
        .order('name')

    // 3. Fetch recent cutting orders created by this supervisor
    const { data: recentOrders } = await supabase
        .from('cutting_orders')
        .select('id, order_no, recipe_id, target_qty, status, created_at')
        .order('created_at', { ascending: false })
        .limit(5)

    return (
        <div className="min-h-screen bg-gray-50 text-gray-900">
            {/* Nav Header */}
            <header className="bg-white shadow">
                <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4 flex justify-between items-center">
                    <div>
                        <h1 className="text-xl font-bold text-gray-900">ApparelFlow ERP</h1>
                        <p className="text-sm text-gray-500">
                            Cutting Supervisor Dashboard &mdash; {session.appUser.email}
                        </p>
                    </div>
                    <form action={logout}>
                        <button type="submit" className="text-sm bg-gray-200 hover:bg-gray-300 px-4 py-2 rounded-md font-medium">
                            Sign Out
                        </button>
                    </form>
                </div>
            </header>

            <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-8">

                    {/* Left Column: Form */}
                    <div className="md:col-span-1">
                        {recipesError ? (
                            <div className="text-red-500">Failed to load recipes.</div>
                        ) : (
                            <CuttingForm recipes={recipes as any || []} />
                        )}
                    </div>

                    {/* Right Column: Recent Orders */}
                    <div className="md:col-span-2">
                        <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-200">
                            <h2 className="text-lg font-bold mb-4">Recent Cutting Orders</h2>

                            {!recentOrders || recentOrders.length === 0 ? (
                                <p className="text-gray-500 text-sm">No recent orders found.</p>
                            ) : (
                                <div className="space-y-4">
                                    {recentOrders.map((order) => {
                                        const r = recipes?.find(rec => rec.id === order.recipe_id)
                                        return (
                                            <div key={order.id} className="border border-gray-100 p-4 rounded-md flex justify-between items-center bg-gray-50">
                                                <div>
                                                    <p className="font-semibold text-gray-900">{order.order_no}</p>
                                                    <p className="text-xs text-gray-500">{r?.name || 'Unknown Recipe'} &mdash; {order.target_qty} units</p>
                                                </div>
                                                <div>
                                                    <span className="px-2 py-1 text-xs font-semibold rounded-full bg-yellow-100 text-yellow-800">
                                                        {order.status}
                                                    </span>
                                                </div>
                                            </div>
                                        )
                                    })}
                                </div>
                            )}
                        </div>
                    </div>

                </div>
            </main>
        </div>
    )
}

import { requireAuth } from '@/lib/auth/server'
import { redirect } from 'next/navigation'

export default async function DashboardPage() {
    let appUser;

    try {
        const session = await requireAuth();
        appUser = session.appUser;
    } catch (error) {
        redirect('/login');
    }

    if (appUser.role === 'cutting_supervisor') {
        redirect('/dashboard/cutting')
    } else if (appUser.role === 'cutting_verifier') {
        redirect('/dashboard/verification')
    } else if (appUser.role === 'sewing_supervisor') {
        redirect('/dashboard/sewing')
    }

    return (
        <div className="p-8">
            <h1>Unknown Role: {appUser.role}</h1>
        </div>
    )
}

'use server'

import { createClient } from '@/lib/supabase/server'
import { requireRole } from '@/lib/auth/server'
import { CuttingOrderSchema } from '@/lib/validations/schema'
import { revalidatePath } from 'next/cache'

export async function createCuttingOrder(formData: FormData) {
    try {
        const session = await requireRole(['cutting_supervisor'])
        const supabase = await createClient()

        // 1. Zod Validation
        const rawData = {
            recipe_id: formData.get('recipe_id') as string,
            target_qty: parseInt(formData.get('target_qty') as string, 10),
            fabric_roll_id: formData.get('fabric_roll_id') as string,
            actual_fabric_yds: parseFloat(formData.get('actual_fabric_yds') as string),
        }

        const validation = CuttingOrderSchema.safeParse(rawData)

        if (!validation.success) {
            return {
                error: 'Validation failed',
                details: validation.error.flatten().fieldErrors,
            }
        }

        const data = validation.data

        // 2. Validate Recipe Existence Server-Side
        const { data: recipe, error: recipeError } = await supabase
            .from('recipes')
            .select('id')
            .eq('id', data.recipe_id)
            .single()

        if (recipeError || !recipe) {
            return { error: 'Selected recipe does not exist or could not be loaded.' }
        }

        // 3. Generate secure server-side order_no: CUT-YYYYMMDD-XXXX
        const dateStr = new Date().toISOString().slice(0, 10).replace(/-/g, '')
        const randomHex = Math.floor(Math.random() * 65535).toString(16).toUpperCase().padStart(4, '0')
        // Using a short millisecond component adds additional collision resistance
        const shortMs = (Date.now() % 1000).toString().padStart(3, '0')
        const order_no = `CUT-${dateStr}-${shortMs}${randomHex}`

        // 4. Call RPC purely atomic
        const { data: newOrderId, error: rpcError } = await supabase.rpc('create_cutting_order_atomic', {
            p_order_no: order_no,
            p_recipe_id: data.recipe_id,
            p_target_qty: data.target_qty,
            p_fabric_roll_id: data.fabric_roll_id,
            p_actual_fabric_yds: data.actual_fabric_yds,
            p_created_by: session.appUser.id, // Using correct public.users.id
        })

        if (rpcError) {
            console.error('RPC Error:', rpcError)
            return { error: `Database error: ${rpcError.message}` }
        }

        revalidatePath('/dashboard/cutting')

        return { success: true, order_no }

    } catch (err: unknown) {
        console.error('Action Exception:', err)
        return { error: err instanceof Error ? err.message : 'An unexpected error occurred' }
    }
}

import { createServerClient } from '@supabase/ssr'
import { NextResponse, type NextRequest } from 'next/server'

export async function updateSession(request: NextRequest) {
    let supabaseResponse = NextResponse.next({
        request,
    })

    const supabase = createServerClient(
        process.env.NEXT_PUBLIC_SUPABASE_URL!,
        process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY || process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
        {
            cookies: {
                getAll() {
                    return request.cookies.getAll()
                },
                setAll(cookiesToSet) {
                    cookiesToSet.forEach(({ name, value, options }) => request.cookies.set(name, value))
                    supabaseResponse = NextResponse.next({
                        request,
                    })
                    cookiesToSet.forEach(({ name, value, options }) =>
                        supabaseResponse.cookies.set(name, value, options)
                    )
                },
            },
        }
    )

    const {
        data: { user },
    } = await supabase.auth.getUser()

    const isAuthRoute = request.nextUrl.pathname.startsWith('/login')
    const isProtected = request.nextUrl.pathname.startsWith('/dashboard') || request.nextUrl.pathname === '/'

    if (!user && isProtected) {
        const url = request.nextUrl.clone()
        url.pathname = '/login'
        return NextResponse.redirect(url)
    }

    if (user && isAuthRoute) {
        const url = request.nextUrl.clone()
        url.pathname = '/'
        return NextResponse.redirect(url)
    }

    return supabaseResponse
}

import { createClient } from '@supabase/supabase-js';
import fs from 'fs';

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL;
const supabaseKey = process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY || process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;
const supabase = createClient(supabaseUrl, supabaseKey);

async function inspectTable(tableName) {
    let output = `[${tableName}]\n`;
    const { data, error } = await supabase.from(tableName).select('*').limit(1);
    if (data && data.length > 0) {
        output += `Columns: ${Object.keys(data[0]).join(', ')}\n`;
    } else {
        const { error: insErr } = await supabase.from(tableName).insert({}).select();
        if (insErr) {
            output += `Insert Error: ${JSON.stringify(insErr)}\n`;
        }
    }
    return output;
}

async function run() {
    const tables = ['users', 'recipes', 'recipe_components', 'cutting_orders', 'verification_items', 'verification_logs'];
    let results = '';
    for (const t of tables) {
        results += await inspectTable(t) + '\n';
    }
    fs.writeFileSync('schema_dump.json', results, 'utf8');
}
run();
